/**
 * Bir ay-başı slug'ından ("2026-10-01") o ayın son gününü ("2026-10-31") üretir.
 * Departure date filtresi seçilen AY ile sınırlıdır; eski "2030-01-01" sabiti
 * "o aydan itibaren her şey" anlamına geliyordu.
 */
export const endOfMonthSlug = (startSlug: string) => {
  const [y, m] = startSlug.split("-").map(Number);
  if (!y || !m) return startSlug;
  const last = new Date(y, m, 0).getDate();
  return `${y}-${String(m).padStart(2, "0")}-${String(last).padStart(2, "0")}`;
};

export const dates = Array.from({ length: 12 }, (_, i) => {
  const d = new Date(now.getFullYear(), now.getMonth() + i, 1);
  const month = months[d.getMonth()];
  const year = d.getFullYear().toString();
  const slug = `${year}-${String(d.getMonth() + 1).padStart(2, "0")}-01`;
  return { month, year, slug };
});

