"use client";
import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import Icon from "@/components/header/icons";

// Arrow chrome (bg/border/shadow) via inline styles — with preflight off +
// global Bootstrap, arbitrary tw- classes for these don't apply reliably
// (same approach as the home-page carousels).
const arrowChrome: CSSProperties = {
  border: "1px solid #e2dced",
  background: "#fff",
  color: "#14101c",
  boxShadow: "0 4px 14px rgba(20,16,28,0.14), 0 1px 3px rgba(20,16,28,0.10)",
};

export default function FilterToolbar({
  activeFilterCount,
  onOpenModal,
  childPages,
  childCategories,
  categories,
  pageUrl,
  quickFilters,
}: {
  activeFilterCount: number;
  onOpenModal: () => void;
  childPages: any[];
  childCategories: any[];
  categories: any[];
  pageUrl: string;
  // Kategori linki olmayan sayfalarda (deals/search) link şeridi yerine açılır
  // hızlı filtre pill'leri (Duration/Departure date/Price) gösterilir.
  quickFilters?: ReactNode;
}) {
  // Same precedence as the legacy nav-scroller: child pages, then child
  // categories, then categories.
  let links: { href: string; title: string; active: boolean }[] = [];
  if (childPages && childPages.length > 0) {
    links = childPages.map((item: any) => ({
      href: item.pageUrl,
      title: item.pageTitle,
      active: item.pageUrl === pageUrl,
    }));
  } else if (childCategories && childCategories.length > 0) {
    links = childCategories.map((item: any) => ({
      href: item.pageUrl,
      title: item.pageTitle,
      active: item.pageUrl === pageUrl,
    }));
  } else if (categories && categories.length > 0) {
    links = categories.map((item: any) => ({
      href: item.pageUrl,
      title: item.pageTitle,
      active: item.pageUrl.replace("/", "") === pageUrl,
    }));
  }

  // İçinde bulunulan kategoriyi listede gösterme — kendini atla, diğerlerini göster.
  links = links.filter((l) => !l.active);

  // Link yoksa (deals/search) onun yerine hızlı filtre pill'lerini göster.
  const hasLinks = links.length > 0;
  const showQuick = !hasLinks && !!quickFilters;
  const hasNav = hasLinks || showQuick;
  const pillCls =
    "tw-flex-none tw-px-3 tw-py-1.5 tw-rounded-full tw-text-[13.5px] tw-font-medium tw-no-underline tw-border tw-border-solid tw-border-[#ebe7f0] tw-transition-colors tw-cursor-pointer ";
  const pillActive = "tw-bg-[#f4eefb] tw-text-[#854ec9] tw-border-[#e7dcf6]";
  const pillIdle =
    "tw-bg-white tw-text-[#14101c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]";

  const navRef = useRef<HTMLDivElement>(null);
  const [edges, setEdges] = useState({ left: false, right: false });
  // Mobile: show the right arrow only as a one-time "you can scroll" hint, then
  // hide it (and never show a left arrow) once the user scrolls/taps — otherwise
  // a persistent arrow eats space and hides the links. Desktop keeps both arrows.
  const [isMobile, setIsMobile] = useState(false);
  const [interacted, setInteracted] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    const apply = () => setIsMobile(mq.matches);
    apply();
    mq.addEventListener("change", apply);
    return () => mq.removeEventListener("change", apply);
  }, []);

  useEffect(() => {
    const el = navRef.current;
    if (!el) return;
    const update = () => {
      setEdges({
        left: el.scrollLeft > 4,
        right: el.scrollLeft + el.clientWidth < el.scrollWidth - 4,
      });
    };
    const onScroll = () => {
      update();
      setInteracted(true);
    };
    update();
    el.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      el.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", update);
    };
  }, [links.length, showQuick]);

  // Desktop: arrows follow the scroll edges. Mobile: only the right arrow, and
  // only until the first interaction (one-time hint); never a left arrow.
  const showLeft = edges.left && !isMobile;
  const showRight = edges.right && (!isMobile || !interacted);

  const scrollByDir = (dir: -1 | 1) => {
    const el = navRef.current;
    if (!el) return;
    el.scrollBy({ left: dir * el.clientWidth * 0.8, behavior: "smooth" });
  };

  return (
    <div className="tw-flex tw-items-center tw-gap-3 tw-flex-nowrap tw-font-display">
      {/* Filter button */}
      <button
        type="button"
        onClick={onOpenModal}
        className="tw-relative tw-flex-none tw-inline-flex tw-items-center tw-gap-2 tw-px-4 tw-py-2 tw-rounded-full tw-text-[14px] tw-font-semibold tw-text-white tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-border-0 tw-cursor-pointer tw-transition-colors"
      >
        <Icon name="sliders" size={16} stroke={2} />
        Filters
        {activeFilterCount > 0 && (
          <span className="tw-inline-grid tw-place-items-center tw-min-w-[18px] tw-h-[18px] tw-px-1 tw-rounded-full tw-bg-white tw-text-[#854ec9] tw-text-[11px] tw-font-bold">
            {activeFilterCount}
          </span>
        )}
      </button>

      {/* Divider */}
      {hasNav && (
        <span
          className="tw-flex-none tw-h-6 tw-w-px tw-bg-[#d8d2e1]"
          aria-hidden="true"
        />
      )}

      {/* Category links — horizontally scrollable with edge fades + arrows */}
      {hasLinks && (
        <div className="tw-relative tw-min-w-0 tw-flex-1">
          {/* Left fade + arrow */}
          {showLeft && (
            <>
              <span
                aria-hidden
                className="tw-pointer-events-none tw-absolute tw-left-0 tw-top-0 tw-bottom-0 tw-w-10 tw-z-[1]"
                style={{
                  background:
                    "linear-gradient(to right, #fff 35%, rgba(255,255,255,0))",
                }}
              />
              <button
                type="button"
                onClick={() => scrollByDir(-1)}
                aria-label="Scroll categories left"
                className="tw-grid tw-place-items-center tw-h-9 tw-w-9 tw-rounded-full tw-z-[2] tw-cursor-pointer"
                style={{
                  position: "absolute",
                  left: 0,
                  top: "50%",
                  transform: "translateY(-50%)",
                  ...arrowChrome,
                }}
              >
                <Icon name="chevDown" size={18} stroke={2.4} className="tw-rotate-90" />
              </button>
            </>
          )}

          <nav
            ref={navRef}
            aria-label="Categories"
            // Own compositing layer (translateZ) so the pill borders always
            // repaint crisply — otherwise the sticky bar's shadow transition
            // can leave their bottom border stale until a hover forces a repaint.
            // tw-py-1 keeps those 1px borders off the scroll container's clip edge.
            style={{ transform: "translateZ(0)" }}
            className="tw-flex tw-items-center tw-gap-2 tw-py-1 tw-overflow-x-auto tw-whitespace-nowrap [scrollbar-width:none] [&::-webkit-scrollbar]:tw-hidden"
          >
            {links.map((link, i) => (
              <a
                key={i}
                href={link.href}
                title={link.title}
                className={pillCls + (link.active ? pillActive : pillIdle)}
              >
                {link.title}
              </a>
            ))}
          </nav>

          {/* Right fade + arrow */}
          {showRight && (
            <>
              <span
                aria-hidden
                className="tw-pointer-events-none tw-absolute tw-right-0 tw-top-0 tw-bottom-0 tw-w-10 tw-z-[1]"
                style={{
                  background:
                    "linear-gradient(to left, #fff 35%, rgba(255,255,255,0))",
                }}
              />
              <button
                type="button"
                onClick={() => scrollByDir(1)}
                aria-label="Scroll categories right"
                className="tw-grid tw-place-items-center tw-h-9 tw-w-9 tw-rounded-full tw-z-[2] tw-cursor-pointer"
                style={{
                  position: "absolute",
                  right: 0,
                  top: "50%",
                  transform: "translateY(-50%)",
                  ...arrowChrome,
                }}
              >
                <Icon name="chevDown" size={18} stroke={2.4} className="tw--rotate-90" />
              </button>
            </>
          )}
        </div>
      )}

      {/* Quick-filter dropdown pills (deals/search). Yatay kaydırılabilir (oksuz,
          gizli scrollbar); popover body'e portal'landığı için scroll kırpmaz. */}
      {showQuick && (
        <div className="tw-flex tw-min-w-0 tw-flex-1 tw-items-center tw-gap-2 tw-overflow-x-auto tw-flex-nowrap tw-py-1 [scrollbar-width:none] [&::-webkit-scrollbar]:tw-hidden">
          {quickFilters}
        </div>
      )}
    </div>
  );
}
