"use client";
import Icon from "@/components/header/icons";
import {
  getActiveFilterChips,
  clearAllFilters,
  buildCityOptions,
} from "./filter-utils";

export default function ActiveChips({
  filterData,
  setFilterData,
  cities,
}: {
  filterData: any;
  setFilterData: (fd: any) => void;
  cities: any[];
}) {
  const cityOptions = buildCityOptions(cities);
  const chips = getActiveFilterChips(filterData, cityOptions);

  if (chips.length === 0) return null;

  return (
    <div className="tw-flex tw-flex-wrap tw-items-center tw-gap-2 tw-font-display">
      {chips.map((chip) => (
        <button
          key={chip.id}
          type="button"
          onClick={() => setFilterData(chip.remove(filterData))}
          className="tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-1.5 tw-rounded-full tw-text-[13px] tw-font-semibold tw-text-[#854ec9] tw-bg-[#f4eefb] tw-border tw-border-solid tw-border-[#e7dcf6] tw-cursor-pointer hover:tw-bg-[#e7dcf6] tw-transition-colors"
        >
          {chip.label}
          <Icon name="close" size={12} stroke={2.4} />
        </button>
      ))}

      <button
        type="button"
        onClick={() => setFilterData(clearAllFilters(filterData))}
        className="tw-text-[13px] tw-font-semibold tw-text-[#5d556c] hover:tw-text-[#14101c] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-px-2 tw-py-1"
      >
        Clear all
      </button>
    </div>
  );
}
