"use client";
import ListingCard from "@/components/tour/card/listing-card";
import getTourPricing from "@/services/tourPricingService";
import { Key, useEffect, useState } from "react";
import { getCookie } from "cookies-next";

export default function TourList({ tours }: { tours: any }) {
  const [priceLoading, setPriceLoading] = useState(true);
  const [prices, setPrices] = useState(
    tours.map((item: any) => {
      return {
        tourId: item.id,
        price: 0,
        oldPrice: 0,
        paxLeft: 0,
        currency: "",
      };
    })
  );

  useEffect(() => {
    setPriceLoading(true);
    getTourPricing(
      tours.map((tour: any) => tour.id),
      getCookie("currency")
    ).then((res) => {
      setPrices(
        res.map((item: any) => {
          return {
            tourId: item.id,
            price: item.price,
            oldPrice: item.old_price,
            paxLeft: item.promotionDetail.pax_left ?? 0,
            currency: item.currency,
          };
        })
      );
      setPriceLoading(false);
    });
  }, [tours]);

  return (
    <div className="tw-grid tw-grid-cols-1 tw-gap-5 sm:tw-grid-cols-2 sm:tw-gap-6 lg:tw-grid-cols-3 xl:tw-grid-cols-4">
      {tours.map(
        (
          item: {
            key: Key | null | undefined;
            id: number;
            detail: any;
            priceInfo: {
              price: number;
              oldPrice: number;
              currency: string;
            };
          },
          index: number
        ) => (
          <ListingCard
            key={item.id}
            detail={item}
            priceLoading={priceLoading}
            priceInfo={prices.find((x: any) => x.tourId === item.id)}
            // First row (4 cards on the xl grid) is above the fold and holds the
            // LCP image — load it eagerly with high priority instead of lazy.
            priority={index < 4}
          />
        )
      )}
    </div>
  );
}
