"use client";
import { useEffect, useRef, useState } from "react";
import Icon from "@/components/header/icons";

const SORT_OPTIONS = [
  { value: "sales_desc", label: "Featured" },
  { value: "rating_desc", label: "Traveler Rating" },
  { value: "price_asc", label: "Price (Low to High)" },
  { value: "price_desc", label: "Price (High to Low)" },
  { value: "duration_days_asc", label: "Duration (Short to Long)" },
  { value: "duration_days_desc", label: "Duration (Long to Short)" },
];

export default function SortSelect({
  filterData,
  setFilterData,
}: {
  filterData: any;
  setFilterData: (fd: any) => void;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  const sortValue = `${filterData.order ?? "sales"}_${
    filterData.order_dir ?? "desc"
  }`;
  const current =
    SORT_OPTIONS.find((o) => o.value === sortValue) ?? SORT_OPTIONS[0];

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node))
        setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  const select = (value: string) => {
    const idx = value.lastIndexOf("_");
    setFilterData({
      ...filterData,
      order: value.slice(0, idx),
      order_dir: value.slice(idx + 1),
    });
    setOpen(false);
  };

  return (
    <div ref={ref} className="tw-relative tw-flex-none tw-font-display">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className="tw-inline-flex tw-items-center tw-gap-1.5 tw-bg-transparent tw-border-0 tw-cursor-pointer tw-p-0 tw-text-[13px]"
      >
        <span className="tw-text-[#5d556c] tw-whitespace-nowrap">Sort by:</span>
        <span className="tw-font-semibold tw-text-[#14101c] tw-whitespace-nowrap">
          {current.label}
        </span>
        <Icon
          name="chevDown"
          size={15}
          className={
            "tw-text-[#5d556c] tw-transition-transform " +
            (open ? "tw-rotate-180" : "")
          }
        />
      </button>

      {open && (
        <div
          role="listbox"
          className="tw-absolute tw-right-0 tw-top-full tw-mt-2 tw-z-30 tw-min-w-[210px] tw-rounded-xl tw-bg-white tw-py-1.5 tw-border tw-border-solid tw-border-[#ebe7f0]"
          style={{ boxShadow: "0 12px 30px rgba(20,16,28,0.14)" }}
        >
          {SORT_OPTIONS.map((o) => (
            <button
              key={o.value}
              type="button"
              role="option"
              aria-selected={o.value === sortValue}
              onClick={() => select(o.value)}
              className={
                "tw-block tw-w-full tw-text-left tw-px-4 tw-py-2 tw-text-[13.5px] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap hover:tw-bg-[#faf9fc] " +
                (o.value === sortValue
                  ? "tw-font-semibold tw-text-[#854ec9]"
                  : "tw-text-[#2a2336]")
              }
            >
              {o.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
