"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";

/**
 * Wraps the filter toolbar so it sticks just under the sticky site header
 * (64px mobile / 84px ≥721px, matching the header row heights). A zero-height
 * sentinel + IntersectionObserver detect the moment the bar becomes "stuck" and
 * reveal a soft shadow only then — no border/shadow while resting at the top.
 */
export default function StickyBar({ children }: { children: ReactNode }) {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [stuck, setStuck] = useState(false);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    let observer: IntersectionObserver | null = null;

    const setup = () => {
      observer?.disconnect();
      const top = window.matchMedia("(min-width: 721px)").matches ? 84 : 64;
      observer = new IntersectionObserver(
        ([entry]) => setStuck(!entry.isIntersecting),
        { rootMargin: `-${top + 1}px 0px 0px 0px`, threshold: 0 }
      );
      observer.observe(sentinel);
    };

    setup();
    window.addEventListener("resize", setup);
    return () => {
      observer?.disconnect();
      window.removeEventListener("resize", setup);
    };
  }, []);

  // Let the page drop the header's shadow + bottom border only while the bar is
  // stuck (so the header + bar read as one block); reverts at the top.
  useEffect(() => {
    document.body.classList.toggle("tsb-filterbar-stuck", stuck);
    return () => document.body.classList.remove("tsb-filterbar-stuck");
  }, [stuck]);

  return (
    <>
      <div ref={sentinelRef} aria-hidden className="tw-h-0" />
      <div
        className="tsb-filterbar tw-sticky tw-top-[64px] min-[721px]:tw-top-[84px] tw-z-40 tw-bg-white tw-py-3"
        // When stuck, match the site header's own border + shadow exactly so it
        // reads as the header sliding down. The shadow/border fade IN smoothly
        // when gained (stuck) and vanish INSTANTLY when lost (un-stuck) — that
        // way there's never a double shadow with the header on the way back up.
        // A 1px transparent border at rest keeps the height stable (no shift).
        style={{
          transition: stuck
            ? "box-shadow .3s ease, border-color .3s ease"
            : "none",
          borderBottom: stuck ? "1px solid #ebe7f0" : "1px solid transparent",
          boxShadow: stuck
            ? "0 1px 0 rgba(255,255,255,0.8), 0 2px 8px rgba(20,16,28,0.04)"
            : "none",
        }}
      >
        {children}
      </div>
    </>
  );
}
