"use client";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Icon from "@/components/header/icons";

/**
 * Toolbar'daki açılır hızlı filtre pill'i (Duration / Departure date / Price …).
 * Popover, body'e portal'lanır (position:fixed) — böylece toolbar'ın yatay-scroll
 * (overflow-x) kapsayıcısı onu kırpmaz. Bir değer seçiliyken pill mor olur ve
 * seçilen etiketi gösterir; "Any" değeri temizler.
 */
export default function QuickFilterPill({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  // İlk seçenek value="" (Any) olmalı.
  options: { value: string; label: string }[];
  value: string;
  onChange: (value: string) => void;
}) {
  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState<{
    top: number;
    left: number;
    minWidth: number;
  } | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const popRef = useRef<HTMLDivElement>(null);

  const place = () => {
    const r = btnRef.current?.getBoundingClientRect();
    if (!r) return;
    setCoords({
      top: r.bottom + 8,
      left: Math.min(r.left, window.innerWidth - 220),
      minWidth: Math.max(r.width, 200),
    });
  };

  useLayoutEffect(() => {
    if (open) place();
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      const t = e.target as Node;
      if (!btnRef.current?.contains(t) && !popRef.current?.contains(t))
        setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    // capture=true → toolbar'ın yatay scroll'unu da yakalar; popover'ı butona
    // göre yeniden konumlar.
    const reposition = () => place();
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    window.addEventListener("scroll", reposition, true);
    window.addEventListener("resize", reposition);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("scroll", reposition, true);
      window.removeEventListener("resize", reposition);
    };
  }, [open]);

  const selected = options.find((o) => o.value === value && o.value !== "");
  const active = !!selected;

  return (
    <div className="tw-relative tw-flex-none">
      <button
        ref={btnRef}
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={
          "tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-1.5 tw-rounded-full tw-text-[13.5px] tw-font-medium tw-border tw-border-solid tw-cursor-pointer tw-transition-colors tw-whitespace-nowrap " +
          (active
            ? "tw-bg-[#f4eefb] tw-text-[#854ec9] tw-border-[#e7dcf6]"
            : "tw-bg-white tw-text-[#14101c] tw-border-[#ebe7f0] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]")
        }
      >
        {active ? selected!.label : label}
        <Icon
          name="chevDown"
          size={14}
          className={"tw-transition-transform " + (open ? "tw-rotate-180" : "")}
        />
      </button>

      {open &&
        coords &&
        createPortal(
          <div
            ref={popRef}
            role="listbox"
            className="tw-font-display tw-max-h-[300px] tw-overflow-y-auto tw-rounded-xl tw-bg-white tw-py-1.5 tw-border tw-border-solid tw-border-[#ebe7f0]"
            style={{
              position: "fixed",
              top: coords.top,
              left: coords.left,
              minWidth: coords.minWidth,
              zIndex: 1100,
              boxShadow: "0 12px 30px rgba(20,16,28,0.14)",
            }}
          >
            {options.map((o) => (
              <button
                key={o.value || "any"}
                type="button"
                role="option"
                aria-selected={o.value === value}
                onClick={() => {
                  onChange(o.value);
                  setOpen(false);
                }}
                className={
                  "tw-block tw-w-full tw-text-left tw-px-4 tw-py-2 tw-text-[13.5px] tw-bg-transparent tw-border-0 tw-cursor-pointer tw-whitespace-nowrap hover:tw-bg-[#faf9fc] " +
                  (o.value === value
                    ? "tw-font-semibold tw-text-[#854ec9]"
                    : "tw-text-[#2a2336]")
                }
              >
                {o.label}
              </button>
            ))}
          </div>,
          document.body
        )}
    </div>
  );
}
