"use client";
import { useState, useEffect, useRef, type ReactNode } from "react";
import { getCookie } from "cookies-next";
import FilterToolbar from "@/components/tour-category-page/filter-toolbar";
import FilterModal from "@/components/tour-category-page/filter-modal";
import ActiveChips from "@/components/tour-category-page/active-chips";
import StickyBar from "@/components/tour-category-page/sticky-bar";
import SortSelect from "@/components/tour-category-page/sort-select";
import {
  getActiveFilterCount,
  buildCityOptions,
  clearAllFilters,
} from "@/components/tour-category-page/filter-utils";
import Icon from "@/components/header/icons";
import TourList from "@/components/tour-category-page/tour-list";
import TourListSkeleton from "@/components/tour-category-page/tour-list-skeleton";
import QuickFilterPill from "@/components/tour-category-page/quick-filter-pill";
import QuickFilterMultiPill from "@/components/tour-category-page/quick-filter-multi-pill";
import getData from "@/services/filterPageService";
import Pagination from "@/components/pagination/pagination";
import {
  durationOptions,
  dates,
  prices,
  operatedLanguages,
  endOfMonthSlug,
} from "@/services/filterPageFilterData";
import priceFormat from "@/helpers/priceFormat";

/**
 * Tur kategori sayfaları, Deals ve Search için ortak liste + filtre kabuğu.
 * Tek merkezi filtre (FilterModal/FilterToolbar) buradan beslenir; sayfalar
 * yalnızca kendi başlık/SEO/footer içeriklerini sağlar.
 *
 * - Kategori sayfası: ilk turlar + filters cache'ten gelir (initialTours/Filters),
 *   ilk yüklemede fetch YOK (withAggregations=false).
 * - Deals/Search: ilk veri yok → mount'ta fetch + agregasyonlardan filters üretilir
 *   (withAggregations=true).
 */
export default function ToursListing({
  params,
  initialFilterData,
  initialTours,
  initialTotal = 0,
  initialFilters = {},
  withAggregations = false,
  enableHashFilters = false,
  showQuickFilters = false,
  footer,
}: {
  params: any;
  initialFilterData: any;
  initialTours?: any[];
  initialTotal?: number;
  initialFilters?: any;
  withAggregations?: boolean;
  enableHashFilters?: boolean;
  showQuickFilters?: boolean;
  footer?: ReactNode;
}) {
  const fetchOnMount = initialTours == null;

  const [loading, setLoading] = useState(fetchOnMount);
  const [tours, setTours] = useState<any>(initialTours ?? []);
  const [totalTours, setTotalTours] = useState(initialTotal);
  const [currentPage, setCurrentPage] = useState(1);
  const [filterData, setFilterData] = useState<any>(initialFilterData);
  const [filters, setFilters] = useState<any>(initialFilters);
  const [modalOpen, setModalOpen] = useState(false);
  const skipFirstFetch = useRef(!fetchOnMount);
  const tourListRef = useRef<HTMLDivElement>(null);

  const activeFilterCount = getActiveFilterCount(
    filterData,
    buildCityOptions(params.cities ?? [])
  );

  // Kategori linki olmayan sayfalarda (deals/search) toolbar'a açılır hızlı filtre
  // pill'leri: Duration / Departure date / Price. Anında filterData'yı günceller
  // (tam filtre için modal hep "Filters" butonunda).
  const currency = getCookie("currency");
  const durKey =
    filterData.duration && filterData.duration.length === 2
      ? `${filterData.duration[0]}-${filterData.duration[1]}`
      : "";
  const priceKey =
    filterData.price && filterData.price.length === 2
      ? `${filterData.price[0]}-${filterData.price[1]}`
      : "";

  const quickFilters = showQuickFilters ? (
    <>
      <QuickFilterPill
        label="Duration"
        value={durKey}
        options={[
          { value: "", label: "Any duration" },
          ...durationOptions
            .filter((o) => o.value !== "any")
            .map((o) => ({ value: o.value, label: o.label })),
        ]}
        onChange={(v) =>
          setFilterData((d: any) => {
            const c = { ...d };
            if (!v) delete c.duration;
            else {
              const [f, t] = v.split("-");
              c.duration = [Number(f), Number(t)];
            }
            return c;
          })
        }
      />
      <QuickFilterPill
        label="Departure date"
        value={filterData.start || ""}
        options={[
          { value: "", label: "Any date" },
          ...dates.map((dt: any) => ({
            value: dt.slug,
            label: `${dt.month} ${dt.year}`,
          })),
        ]}
        onChange={(v) =>
          setFilterData((d: any) => {
            const c = { ...d };
            if (!v) {
              delete c.start;
              delete c.end;
            } else {
              c.start = v;
              c.end = endOfMonthSlug(v);
            }
            return c;
          })
        }
      />
      <QuickFilterPill
        label="Price"
        value={priceKey}
        options={[
          { value: "", label: "Any price" },
          ...prices.map((p: any) => ({
            value: `${p.from}-${p.to}`,
            label: `${priceFormat({ amount: p.from, currency })} - ${priceFormat({
              amount: p.to,
              currency,
            })}`,
          })),
        ]}
        onChange={(v) =>
          setFilterData((d: any) => {
            const c = { ...d };
            if (!v) delete c.price;
            else {
              const [f, t] = v.split("-");
              c.price = [f, t];
            }
            return c;
          })
        }
      />
      <QuickFilterMultiPill
        label="Language"
        values={filterData.languages ?? []}
        options={operatedLanguages.map((l: any) => ({
          value: l.slug,
          label: l.name,
        }))}
        onChange={(vals) =>
          setFilterData((d: any) => ({ ...d, languages: vals }))
        }
      />
    </>
  ) : undefined;

  // Belirli bir Y'ye yumuşak kaydırma (iOS Safari'de native smooth güvenilmez).
  const animateScrollTo = (targetY: number) => {
    const startY =
      window.scrollY ||
      document.documentElement.scrollTop ||
      document.body.scrollTop ||
      0;
    const distance = targetY - startY;
    if (Math.abs(distance) < 2) return;

    const duration = 400;
    const startTime = performance.now();
    const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

    const setY = (y: number) => {
      window.scrollTo(0, y);
      document.documentElement.scrollTop = y;
      document.body.scrollTop = y;
    };

    const step = (now: number) => {
      const t = Math.min((now - startTime) / duration, 1);
      setY(Math.round(startY + distance * easeOutCubic(t)));
      if (t < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  // Kartlar sticky filtre barının hemen altında başlasın (kesilmesin).
  const scrollToList = () => {
    const el = tourListRef.current;
    if (!el) return;
    const stickyTop = window.matchMedia("(min-width: 721px)").matches ? 84 : 64;
    const bar = document.querySelector<HTMLElement>(".tsb-filterbar");
    const offset = stickyTop + (bar?.offsetHeight ?? 0) + 12;
    const targetY = Math.max(
      el.getBoundingClientRect().top + window.scrollY - offset,
      0
    );
    const currentY =
      window.scrollY ||
      document.documentElement.scrollTop ||
      document.body.scrollTop ||
      0;
    if (currentY <= targetY + 2) return;
    animateScrollTo(targetY);
  };

  const pagination = async ({ page }: { page: number }) => {
    scrollToList();
    setLoading(true);
    await getData({
      page,
      filterData,
      currency: getCookie("currency"),
    }).then((res) => {
      setTours(res.tours);
      setLoading(false);
    });
  };

  useEffect(() => {
    if (skipFirstFetch.current) {
      skipFirstFetch.current = false;
      return;
    }
    scrollToList();
    setLoading(true);
    getData({
      page: 1,
      filterData,
      currency: getCookie("currency"),
      aggregations: withAggregations,
    }).then((res) => {
      setTotalTours(res.total);
      setCurrentPage(1);
      setTours(res.tours);
      if (withAggregations && res.filters) setFilters(res.filters);
      setLoading(false);
    });
  }, [filterData]); // eslint-disable-line react-hooks/exhaustive-deps

  // Kategori sayfasındaki hash tabanlı ön-filtre (#destination=...,activity=...).
  useEffect(() => {
    if (!enableHashFilters) return;
    let hash = window.location.hash;
    if (!hash || hash === "") return;

    let next = filterData;
    hash = hash.substring(1);
    hash.split(",").forEach((item: any) => {
      const [key, val] = item.split("=");
      if (val === "" || val === undefined) return;
      if (key === "destination") next = { ...next, destination: val };
      if (key === "activity") next = { ...next, category: val };
      if (key === "departure-date")
        next = { ...next, start: val, end: endOfMonthSlug(val) };
      if (key === "budget-class") next = { ...next, lodging: [val] };
      if (key === "service-type") next = { ...next, service_type: [val] };
      if (key === "duration-from") next = { ...next, duration: [val, 999] };
      if (key === "promotion_type") next = { ...next, promotion_type: val };
    });
    setFilterData(next);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <>
      {/* Bar header'ın altına yapışınca header'ın gölge/border'ını düşür (çift
          gölge olmasın); yukarı çıkınca yumuşak geri kazandır. */}
      <style>{`
        .tsb-app-header { transition: box-shadow .3s ease, border-color .3s ease; }
        body.tsb-filterbar-stuck .tsb-app-header { transition: none; box-shadow: none !important; border-bottom-color: transparent !important; }
      `}</style>

      {/* Full-width filter band — header gibi tam genişlik, iç container hizalı. */}
      <StickyBar>
        <div className="tw-mx-auto tw-w-full tw-max-w-[1320px] tw-px-3">
          <FilterToolbar
            activeFilterCount={activeFilterCount}
            onOpenModal={() => setModalOpen(true)}
            childPages={params.childPages}
            childCategories={params.childCategories}
            categories={params.categories}
            pageUrl={params.pageUrl}
            quickFilters={quickFilters}
          />
        </div>
      </StickyBar>

      <div className="tw-mx-auto tw-w-full tw-max-w-[1320px] tw-px-3 tw-font-display tw-pb-6">
        <div className="tw-mt-3 tw-flex tw-items-center tw-justify-between tw-gap-3">
          <span className="tw-text-[13px] tw-text-[#5d556c]">
            {loading ? (
              <span className="tw-inline-block tw-h-3.5 tw-w-32 tw-rounded tw-bg-[#ece9f1] tw-animate-pulse tw-align-middle" />
            ) : totalTours > 0 ? (
              <>
                {(Math.ceil(totalTours / 100) * 100).toLocaleString("en-US")}
                <span className="tw-relative tw-top-[-1px]">+</span> tours &amp;
                activities
              </>
            ) : (
              "No results"
            )}
          </span>
          <SortSelect filterData={filterData} setFilterData={setFilterData} />
        </div>

        {activeFilterCount > 0 && (
          <div className="tw-mt-3">
            <ActiveChips
              filterData={filterData}
              setFilterData={setFilterData}
              cities={params.cities ?? []}
            />
          </div>
        )}

        <div ref={tourListRef} className="tw-mt-4" />
        {loading ? (
          <TourListSkeleton />
        ) : (
          <TourList tours={tours} />
        )}
        {!loading && (
          <div className="tw-mt-6">
            <Pagination
              currentPage={currentPage}
              totalCount={totalTours}
              pageSize="20"
              onPageChange={(page: number) => {
                setCurrentPage(page);
                pagination({ page });
              }}
            />
          </div>
        )}
        {totalTours === 0 && !loading && (
          <div className="tw-flex tw-flex-col tw-items-center tw-justify-center tw-text-center tw-py-16 tw-px-4">
            <div className="tw-w-20 tw-h-20 tw-rounded-full tw-grid tw-place-items-center tw-bg-[#f4eefb] tw-text-[#854ec9] tw-mb-5">
              <Icon name="search" size={36} stroke={1.8} />
            </div>
            <h3 className="tw-text-[20px] tw-font-bold tw-text-[#14101c] tw-mb-2 tw-mt-0">
              Let&apos;s widen your search
            </h3>
            <p className="tw-text-[15px] tw-leading-relaxed tw-text-[#5d556c] tw-max-w-[420px] tw-m-0">
              We couldn&apos;t find any tours matching your filters. Try
              adjusting or clearing them to see more results.
            </p>
            {activeFilterCount > 0 && (
              <button
                type="button"
                onClick={() => setFilterData(clearAllFilters(filterData))}
                className="tw-mt-6 tw-px-6 tw-py-2.5 tw-rounded-full tw-text-[14px] tw-font-semibold tw-text-white tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-border-0 tw-cursor-pointer tw-transition-colors"
              >
                Clear all filters
              </button>
            )}
          </div>
        )}

        {footer}
      </div>

      <FilterModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        filters={filters}
        filterData={filterData}
        onApply={(draft: any) => setFilterData(draft)}
        params={params}
      />
    </>
  );
}
