"use client";
import { useEffect, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Icon from "@/components/header/icons";

/**
 * Toolbar'daki çoklu-seçim hızlı filtre pill'i (ör. Language). QuickFilterPill ile
 * aynı portal/konumlama mantığı, ama popover checkbox listesi (seçince kapanmaz) ve
 * pill seçili adedi "(N)" gösterir. "Clear" ile hepsi temizlenir.
 */
export default function QuickFilterMultiPill({
  label,
  options,
  values,
  onChange,
}: {
  label: string;
  options: { value: string; label: string }[];
  values: string[];
  onChange: (values: string[]) => void;
}) {
  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState<{
    top: number;
    left: number;
    minWidth: number;
  } | null>(null);
  const btnRef = useRef<HTMLButtonElement>(null);
  const popRef = useRef<HTMLDivElement>(null);

  const place = () => {
    const r = btnRef.current?.getBoundingClientRect();
    if (!r) return;
    setCoords({
      top: r.bottom + 8,
      left: Math.min(r.left, window.innerWidth - 240),
      minWidth: Math.max(r.width, 220),
    });
  };

  useLayoutEffect(() => {
    if (open) place();
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      const t = e.target as Node;
      if (!btnRef.current?.contains(t) && !popRef.current?.contains(t))
        setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    const reposition = () => place();
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    window.addEventListener("scroll", reposition, true);
    window.addEventListener("resize", reposition);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
      window.removeEventListener("scroll", reposition, true);
      window.removeEventListener("resize", reposition);
    };
  }, [open]);

  const count = values.length;
  const active = count > 0;
  const toggle = (v: string) =>
    onChange(values.includes(v) ? values.filter((x) => x !== v) : [...values, v]);

  return (
    <div className="tw-relative tw-flex-none">
      <button
        ref={btnRef}
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={
          "tw-inline-flex tw-items-center tw-gap-1.5 tw-px-3 tw-py-1.5 tw-rounded-full tw-text-[13.5px] tw-font-medium tw-border tw-border-solid tw-cursor-pointer tw-transition-colors tw-whitespace-nowrap " +
          (active
            ? "tw-bg-[#f4eefb] tw-text-[#854ec9] tw-border-[#e7dcf6]"
            : "tw-bg-white tw-text-[#14101c] tw-border-[#ebe7f0] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]")
        }
      >
        {label}
        {active && (
          <span className="tw-inline-grid tw-place-items-center tw-min-w-[18px] tw-h-[18px] tw-px-1 tw-rounded-full tw-bg-[#854ec9] tw-text-white tw-text-[11px] tw-font-bold">
            {count}
          </span>
        )}
        <Icon
          name="chevDown"
          size={14}
          className={"tw-transition-transform " + (open ? "tw-rotate-180" : "")}
        />
      </button>

      {open &&
        coords &&
        createPortal(
          <div
            ref={popRef}
            className="tw-font-display tw-max-h-[320px] tw-overflow-y-auto tw-rounded-xl tw-bg-white tw-py-1.5 tw-border tw-border-solid tw-border-[#ebe7f0]"
            style={{
              position: "fixed",
              top: coords.top,
              left: coords.left,
              minWidth: coords.minWidth,
              zIndex: 1100,
              boxShadow: "0 12px 30px rgba(20,16,28,0.14)",
            }}
          >
            {options.map((o) => {
              const checked = values.includes(o.value);
              return (
                <label
                  key={o.value}
                  className="tw-flex tw-items-center tw-gap-2.5 tw-px-4 tw-py-2 tw-cursor-pointer hover:tw-bg-[#faf9fc] tw-text-[13.5px] tw-text-[#2a2336]"
                >
                  <input
                    type="checkbox"
                    checked={checked}
                    onChange={() => toggle(o.value)}
                    className="tw-w-4 tw-h-4 tw-accent-[#854ec9] tw-cursor-pointer tw-flex-none"
                  />
                  {o.label}
                </label>
              );
            })}
            {active && (
              <button
                type="button"
                onClick={() => onChange([])}
                className="tw-block tw-w-full tw-text-left tw-px-4 tw-py-2 tw-mt-1 tw-border-0 tw-border-t tw-border-solid tw-border-[#ebe7f0] tw-bg-transparent tw-text-[13px] tw-font-semibold tw-text-[#854ec9] tw-cursor-pointer hover:tw-bg-[#faf9fc]"
              >
                Clear
              </button>
            )}
          </div>,
          document.body
        )}
    </div>
  );
}
