import { getCookie } from "cookies-next";
import {
  dates,
  tourTypes,
  promotionTypes,
  accommodationTypes,
  guidingTypes,
  operatedLanguages,
  ageRange,
  categoryActivities,
  durationOptions,
} from "@/services/filterPageFilterData";
import priceFormat from "@/helpers/priceFormat";

export type FilterChip = {
  id: string;
  label: string;
  // Returns a new filterData with this filter removed.
  remove: (fd: any) => any;
};

export type CityOption = { value: any; label: string };

const nameOf = (list: any[], slug: string) =>
  list.find((x: any) => x.slug === slug)?.name ?? slug;

const removeFromArray = (fd: any, field: string, val: string) => ({
  ...fd,
  [field]: (fd[field] ?? []).filter((x: string) => x !== val),
});

const omit = (fd: any, ...keys: string[]) => {
  const copy = { ...fd };
  keys.forEach((k) => delete copy[k]);
  return copy;
};

/**
 * Builds the list of active (user-applied) filters as removable chips.
 * Page-level params (destination/category/company) and sort (order/order_dir)
 * are intentionally excluded — they are not user toggles.
 */
export function getActiveFilterChips(
  fd: any,
  cities: CityOption[] = []
): FilterChip[] {
  const chips: FilterChip[] = [];

  (fd.service_types ?? []).forEach((s: string) =>
    chips.push({
      id: `st-${s}`,
      label: nameOf(tourTypes, s),
      remove: (f) => removeFromArray(f, "service_types", s),
    })
  );

  (fd.accommodations ?? []).forEach((s: string) =>
    chips.push({
      id: `ac-${s}`,
      label: nameOf(accommodationTypes, s),
      remove: (f) => removeFromArray(f, "accommodations", s),
    })
  );

  (fd.guiding ?? []).forEach((s: string) =>
    chips.push({
      id: `gd-${s}`,
      label: nameOf(guidingTypes, s),
      remove: (f) => removeFromArray(f, "guiding", s),
    })
  );

  (fd.languages ?? []).forEach((s: string) =>
    chips.push({
      id: `lg-${s}`,
      label: nameOf(operatedLanguages, s),
      remove: (f) => removeFromArray(f, "languages", s),
    })
  );

  (fd.activities ?? []).forEach((s: string) =>
    chips.push({
      id: `act-${s}`,
      label:
        categoryActivities.find((x: any) => x.slug === s)?.name ?? s,
      remove: (f) => removeFromArray(f, "activities", s),
    })
  );

  if (fd.promotion_type)
    chips.push({
      id: "promo",
      label: nameOf(promotionTypes, fd.promotion_type),
      remove: (f) => ({ ...f, promotion_type: "" }),
    });

  if (fd.duration && fd.duration.length === 2) {
    const key = `${fd.duration[0]}-${fd.duration[1]}`;
    const opt = durationOptions.find((o) => o.value === key);
    chips.push({
      id: "dur",
      label: opt ? opt.label : `${fd.duration[0]}–${fd.duration[1]} days`,
      remove: (f) => omit(f, "duration"),
    });
  }

  if (fd.start) {
    const d = dates.find((x: any) => x.slug === fd.start);
    chips.push({
      id: "date",
      label: d ? `${d.month} ${d.year}` : "Departure date",
      remove: (f) => omit(f, "start", "end"),
    });
  }

  if (fd.price && fd.price.length === 2) {
    const currency = getCookie("currency");
    chips.push({
      id: "price",
      label:
        priceFormat({ amount: Number(fd.price[0]), currency }) +
        " - " +
        priceFormat({ amount: Number(fd.price[1]), currency }),
      remove: (f) => omit(f, "price"),
    });
  }

  if (fd.suitable)
    chips.push({
      id: "age",
      label: nameOf(ageRange, fd.suitable),
      remove: (f) => omit(f, "suitable"),
    });

  if (fd.start_location)
    chips.push({
      id: "start-loc",
      label:
        "From: " +
        (fd.start_location_name ||
          cities.find((c) => c.value === fd.start_location)?.label ||
          "Start city"),
      remove: (f) => ({ ...f, start_location: "", start_location_name: "" }),
    });

  if (fd.end_location)
    chips.push({
      id: "end-loc",
      label:
        "To: " +
        (fd.end_location_name ||
          cities.find((c) => c.value === fd.end_location)?.label ||
          "End city"),
      remove: (f) => ({ ...f, end_location: "", end_location_name: "" }),
    });

  return chips;
}

export const getActiveFilterCount = (fd: any, cities: CityOption[] = []) =>
  getActiveFilterChips(fd, cities).length;

/** Clears all user-applied filters while keeping page params + sort. */
export function clearAllFilters(fd: any) {
  const cleared = {
    ...fd,
    service_types: [],
    accommodations: [],
    guiding: [],
    languages: [],
    activities: [],
    lodging: [],
    promotion_type: "",
    start_location: "",
    end_location: "",
    start_location_name: "",
    end_location_name: "",
  };
  return omit(cleared, "duration", "start", "end", "price", "suitable");
}

/** Maps the raw page `cities` param into react-select style options. */
export function buildCityOptions(cities: any[] = []): CityOption[] {
  return cities
    .slice()
    .sort((a: any, b: any) =>
      a.pageTitle < b.pageTitle ? -1 : a.pageTitle > b.pageTitle ? 1 : 0
    )
    .map((c: any) => ({
      value: c.locationId,
      label: c.pageTitle.replace(" Tours", ""),
    }));
}
